    # Split the query into words
    query_words = query.split()

    # Find the patches that match the query words
    patches = []
    for word in query_words:
        patches += image_patch.find(word)

    # If no patches were found, return a failure message
    if not patches:
        return "No matching patches found."

    # If multiple patches were found, sort them by descending order of size
    if len(patches) > 1:
        patches.sort(key=lambda patch: -patch.compute_depth())

    # Return the answer to the query
    return patches[0].simple_query("What color is it?")

